namespace Gridline.Docs;

/// <summary>
/// OpenAPI document (/openapi/v1.json, generated by Microsoft.AspNetCore.OpenApi) and a Swagger UI page at /swagger.
/// The page has a small sign-in bar: it calls /api/auth/login and sends the token as "Authorization: Bearer …" on every try-out.
/// On in Development, or anywhere when Swagger:Enabled = true.
/// </summary>
public static class Swagger
{
    public static bool Enabled(WebApplicationBuilder b) => !b.Environment.IsProduction() || b.Configuration.GetValue<bool>("Swagger:Enabled");

    public static void AddServices(WebApplicationBuilder b)
    {
#if !NO_OPENAPI
        b.Services.AddOpenApi(o => o.ShouldInclude = d => d.RelativePath?.StartsWith("api/") == true);
#endif
    }

    public static void Map(WebApplication app)
    {
#if !NO_OPENAPI
        app.MapOpenApi("/openapi/{documentName}.json").AllowAnonymous();
#endif
        app.MapGet("/swagger", () => Results.Content(Page, "text/html; charset=utf-8")).AllowAnonymous().ExcludeFromDescription();
        app.MapGet("/swagger/index.html", () => Results.Redirect("/swagger")).AllowAnonymous().ExcludeFromDescription();
    }

    const string Page = """
        <!doctype html>
        <html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
        <title>Gridline API · Swagger</title>
        <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5.17.14/swagger-ui.css">
        <style>
          body{margin:0;font-family:system-ui,-apple-system,Segoe UI,sans-serif;background:#fff}
          .gl{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:10px 20px;background:#1b1530;color:#fff}
          .gl b{font-size:15px;margin-right:12px}.gl b i{color:#FF7A2F;font-style:normal}
          .gl input{padding:6px 8px;border-radius:6px;border:1px solid #5b4b8a;background:#2a2147;color:#fff;min-width:210px}
          .gl button{padding:6px 12px;border-radius:6px;border:0;background:#6A32D4;color:#fff;cursor:pointer}
          .gl button.s{background:#3a2f5c}.gl span{font-size:12px;opacity:.85;margin-left:6px}
          .swagger-ui .topbar{display:none}
        </style></head>
        <body>
        <div class="gl"><b>Gridline<i>.</i> API</b>
          <input id="em" type="email" placeholder="email" value="demo@northshore.example">
          <input id="pw" type="password" placeholder="password">
          <button id="si">Sign in</button><button class="s" id="so">Sign out</button><span id="st"></span></div>
        <div id="swagger"></div>
        <script src="https://cdn.jsdelivr.net/npm/swagger-ui-dist@5.17.14/swagger-ui-bundle.js"></script>
        <script>
          const KEY = 'gridline.swagger.token';
          const get = () => { try { return localStorage.getItem(KEY) } catch { return null } };
          const set = t => { try { t ? localStorage.setItem(KEY, t) : localStorage.removeItem(KEY) } catch {} ; show() };
          const st = document.getElementById('st');
          function show() { st.textContent = get() ? 'Signed in · requests carry the token' : 'Not signed in · only public endpoints will work' }
          document.getElementById('si').onclick = async () => {
            st.textContent = 'Signing in…';
            const r = await fetch('/api/auth/login', { method: 'POST', headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ email: document.getElementById('em').value, password: document.getElementById('pw').value }) });
            const j = await r.json().catch(() => ({}));
            if (r.ok) { set(j.accessToken); st.textContent = 'Signed in as ' + j.me.name } else st.textContent = j.detail || ('Sign-in failed (' + r.status + ')');
          };
          document.getElementById('so').onclick = () => set(null);
          show();
          SwaggerUIBundle({
            url: '/openapi/v1.json', dom_id: '#swagger', deepLinking: true, displayRequestDuration: true, tryItOutEnabled: true,
            persistAuthorization: true, filter: true, docExpansion: 'list',
            requestInterceptor: req => { const t = get(); if (t && !req.headers.Authorization) req.headers.Authorization = 'Bearer ' + t; req.headers['X-Tab-Id'] = 'swagger'; return req; },
          });
        </script></body></html>
        """;
}
